/**
 * Supabase Edge Function: summarize-discussion
 *
 * Takes the transcript of a discussion and returns a structured Hebrew
 * summary generated by Gemini, focused on action items. The "סיכום חי" page
 * calls it when recording stops (or on demand).
 *
 * The transcript may contain:
 *   - "[הערה ידנית] ..."  lines typed by the scribe (authoritative)
 *   - a "=== מכאן: סיכום הבכיר ===" marker — everything after it is the senior
 *     participant's closing summary, which is the primary source.
 *
 * Required Edge Function secrets:
 *   GEMINI_API_KEY   – API key for the Gemini API (Google AI Studio / Gemini Enterprise)
 * Optional:
 *   GEMINI_MODEL     – model id, defaults to "gemini-2.5-flash"
 *
 * JWT verification is left on (Supabase default), so only signed-in users of
 * the app can call it.
 *
 * Deployed via the deploy-supabase-functions.yml CI workflow.
 */

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
};

const MAX_TRANSCRIPT_CHARS = 200_000;

const SYSTEM_PROMPT = `אתה רשם דיונים מקצועי ביחידה צבאית. תקבל תמלול אוטומטי (ייתכנו שגיאות זיהוי דיבור) של דיון.
המטרה העיקרית: חילוץ מדויק של המשימות (action items) — מה צריך לעשות, מי אחראי, ועד מתי.

מקורות לפי סדר חשיבות:
1. סיכום הבכיר — כל מה שמופיע אחרי השורה "=== מכאן: סיכום הבכיר ===" (אם קיימת). זה הסיכום הקובע של הדיון. אם אין שורה כזו — לרוב ההקלטה כולה היא דברי הסיכום של הבכיר בסוף הדיון; התייחס לדיבור המתומלל כסיכום הקובע.
2. שורות שמתחילות ב-"[הערה ידנית]" — נכתבו ידנית על ידי הרשם ונחשבות מדויקות.
3. שאר הדיון — רקע והקשר בלבד. השתמש בו כדי להשלים פרטים (אחראי, מועד, הקשר) למשימות ולהחלטות שנאמרו בסיכום.
אם יש סתירה בין גוף הדיון לבין סיכום הבכיר — סיכום הבכיר קובע.

כתוב סיכום בעברית, תמציתי ומדויק, במבנה הבא בדיוק (טקסט רגיל, בלי Markdown, בלי כוכביות או #):

נושא הדיון:
<שורה אחת>

משימות:
- <משימה> — אחראי: <שם או "לא צוין"> — מועד: <מועד או "לא צוין">

החלטות:
- ...

עיקרי הדברים:
- ...

נקודות פתוחות:
- ...

כללים:
- כל משימה בשורה נפרדת, מנוסחת כפעולה ברורה (פועל + מה), עם אחראי ומועד אם נאמרו.
- אל תשמיט משימה שנאמרה בסיכום הבכיר, גם אם נשמעת קטנה.
- "עיקרי הדברים" — קצר, עד 5 נקודות.
- הסתמך רק על מה שנאמר בתמלול. אל תמציא החלטות, שמות או מועדים.
- אם אין תוכן לסעיף, כתוב "- אין".
- תקן שגיאות זיהוי דיבור ברורות לפי ההקשר ורשימת המשתתפים.
- הדיון מתנהל בעברית עם מילים ומונחים באנגלית. השאר מונחים באנגלית באותיות לטיניות כפי שנאמרו (למשל deadline, API) — אל תתרגם ואל תתעתק אותם לעברית. אם מונח באנגלית הופיע בתמלול בתעתיק עברי שגוי, כתוב אותו באנגלית.
- ייתכן שהדיון עוד לא הסתיים — במקרה כזה סכם את מה שנאמר עד כה.`;

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }
  if (req.method !== "POST") return json({ error: "Method not allowed" }, 405);

  const apiKey = Deno.env.get("GEMINI_API_KEY");
  if (!apiKey) return json({ error: "GEMINI_API_KEY is not configured" }, 500);
  const model = Deno.env.get("GEMINI_MODEL") || "gemini-2.5-flash";

  let body: { discussionName?: string; participants?: string[]; seniorName?: string; transcript?: string };
  try {
    body = await req.json();
  } catch {
    return json({ error: "Invalid JSON body" }, 400);
  }

  const transcript = (body.transcript ?? "").trim();
  if (!transcript) return json({ error: "Transcript is empty" }, 400);

  const participants = (body.participants ?? []).filter(Boolean).join(", ") || "לא צוינו";
  const userText =
    `שם הדיון: ${body.discussionName || "לא צוין"}\n` +
    `משתתפים: ${participants}\n` +
    `הבכיר שמסכם את הדיון: ${body.seniorName || "לא צוין"}\n\n` +
    `תמלול:\n${transcript.slice(-MAX_TRANSCRIPT_CHARS)}`;

  try {
    const res = await fetch(
      `https://generativelanguage.googleapis.com/v1beta/models/${encodeURIComponent(model)}:generateContent`,
      {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-goog-api-key": apiKey },
        body: JSON.stringify({
          systemInstruction: { parts: [{ text: SYSTEM_PROMPT }] },
          contents: [{ role: "user", parts: [{ text: userText }] }],
          generationConfig: { temperature: 0.2 },
        }),
      }
    );

    const data = await res.json().catch(() => null);
    if (!res.ok) {
      const msg = data?.error?.message ?? `Gemini request failed (${res.status})`;
      return json({ error: msg }, 502);
    }

    const summary: string = (data?.candidates?.[0]?.content?.parts ?? [])
      .map((p: { text?: string }) => p.text ?? "")
      .join("")
      .trim();

    if (!summary) {
      const reason = data?.candidates?.[0]?.finishReason ?? data?.promptFeedback?.blockReason ?? "unknown";
      return json({ error: `Gemini returned no text (reason: ${reason})` }, 502);
    }

    return json({ summary, model });
  } catch (err) {
    return json({ error: err instanceof Error ? err.message : String(err) }, 500);
  }
});
